def M(wiki, nerve, roots, artery, action, check, **parts):
    """One muscle concept. `check`: regex that the infobox action must contain for the action to count as agreed.
    `parts`: ZA part name -> overrides (nerve/artery/action/check) for parts with their own supply or action."""
    return {'wiki': wiki, 'nerve': nerve, 'roots': roots, 'artery': artery, 'action': action, 'check': check, 'parts': parts}


